pub(super) struct Charge {
    budget: Arc<Budget>,
    amount: usize,
}
impl Charge {
    fn resize(&mut self, amount: usize) -> Result<(), i32> {
        if amount > self.amount {
50→            let mut extra = self.budget.take(amount - self.amount, TOTAL_LIMIT)?;
            extra.amount = 0;
