async fn bind_socket(socket: &Path, session: &str) -> Result<zbus::Connection, LungsError> {
    let stream = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT, tokio::net::UnixStream::connect(socket))
        .await.map_err(|_| LungsError::Transport("lungs socket connection timed out".into()))?
        .map_err(|error| LungsError::Transport(format!("connect to {}: {error}", socket.display())))?;
    let connection = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT,
        zbus::connection::Builder::unix_stream(stream).p2p()
            .auth_mechanism(zbus::connection::AuthMechanism::Anonymous).build())
        .await.map_err(|_| LungsError::Transport("lungs socket negotiation timed out".into()))?
        .map_err(|error| LungsError::Transport(format!("lungs socket: {error}")))?;
290→    let lungs = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT,
        Proxy::new(&connection, PLUGIN_BUS_NAME, LUNGS_OBJECT_PATH, LUNGS_INTERFACE))
        .await.map_err(|_| LungsError::Transport("lungs bind proxy timed out".into()))?
        .map_err(|error| LungsError::Transport(format!("lungs bind proxy: {error}")))?;
    let binding = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT, async {
        if session.is_empty() { lungs.call("BindCurrentContainer", &()).await }
        else { lungs.call("Bind", &(session,)).await }
    }).await.map_err(|_| LungsError::Transport("lungs identity bind timed out".into()))?;
    let bound: bool = binding.map_err(|error| match refusal(&error) {
        true => LungsError::Registration(error.to_string()),
300→        false => LungsError::Transport(format!("bind: {error}")),
    })?;
    if !bound { return Err(LungsError::Registration("bridge declined to bind this session".into())); }
    drop(lungs);
    Ok(connection)
}

pub async fn pickup_mounted_invocation(ticket: &str, pins: &[crate::mounted::MountPin; 2]) -> Result<(crate::mounted::MountedInvocation, crate::invocation::Deadline)> {
    let started = std::time::Instant::now();
    anyhow::ensure!(uuid::Uuid::parse_str(ticket)?.to_string() == ticket, "invalid mounted ticket");
310→    let connection = bind_socket(Path::new("/run/3tched-lungs.socket"), "").await?;
    let proxy = Proxy::new(&connection, PLUGIN_BUS_NAME, LUNGS_OBJECT_PATH, LUNGS_INTERFACE).await?;
    let pins = serde_json::to_string(pins)?;
    let (body, remaining_ms): (String, u64) = tokio::time::timeout(LUNGS_NEGOTIATION_TIMEOUT,
        proxy.call("PickupMountedInvocation", &(ticket, pins))).await
